from fastapi.responses import HTMLResponse
from .main import app

BANK = r'''<!doctype html><html lang="ar" dir="rtl"><meta name="viewport" content="width=device-width,initial-scale=1"><title>بنك الأسئلة</title><style>
body{font-family:system-ui;background:#f5f7fb;margin:0;color:#172033}main{max-width:1400px;margin:auto;padding:16px}.box{background:#fff;border-radius:16px;padding:14px;margin:10px 0;box-shadow:0 3px 14px #0000000a}.top,.filters{display:flex;gap:8px;flex-wrap:wrap;align-items:center}input,select,button{padding:10px;border:1px solid #ccd2dd;border-radius:9px;font:inherit}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}.card{background:#f8fafc;border-radius:12px;padding:12px}.grid{display:grid;grid-template-columns:1fr 340px;gap:12px}.q{padding:11px;border-bottom:1px solid #eee;cursor:pointer}.q:hover{background:#f8fafc}.tag{display:inline-block;padding:3px 7px;border-radius:999px;background:#eef2ff;font-size:12px;margin-left:4px}.muted{color:#667085;font-size:13px}.detail{white-space:pre-wrap;background:#f7f8fa;padding:10px;border-radius:8px}.pager{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:8px 0}.pager button:disabled{opacity:.45;cursor:not-allowed}@media(max-width:900px){.grid{grid-template-columns:1fr}}
</style><main><h1>بنك الأسئلة</h1><div class="box top"><a href="/admin/dashboard">جلسة الإدارة</a><a href="/admin/workflow">مسار المراجعة</a><a href="/practice">واجهة الطالب</a><span id="msg"></span></div>
<div class="box"><div id="cards" class="cards"></div></div>
<div class="box filters"><select id="subject"><option value="">كل المواد</option></select><select id="grade"><option value="">كل الصفوف</option></select><select id="curriculum"><option value="">كل إصدارات المنهج</option></select><select id="term"><option value="">كل الترمات</option></select><select id="unit"><option value="">كل الوحدات</option></select><select id="chapter"><option value="">كل الأبواب</option></select><select id="lesson"><option value="">كل الدروس</option></select><select id="qtype"><option value="">كل الأنواع</option><option value="mcq">اختيار من متعدد</option><option value="numeric">مسألة حسابية</option><option value="essay">مقالي</option><option value="unknown">غير مصنف</option></select><select id="difficulty"><option value="">كل الصعوبات</option><option value="easy">سهل</option><option value="medium">متوسط</option><option value="hard">صعب</option><option value="unclassified">غير مصنف</option></select><select id="state"><option value="">كل الحالات</option><option value="draft">مسودة</option><option value="cropped">تم القص</option><option value="reviewed">تمت المراجعة</option><option value="approved">معتمد</option></select><button onclick="resetPage()">تطبيق الفلاتر</button><button onclick="resetFilters()">مسح الفلاتر</button></div>
<div class="grid"><div class="box"><div id="count" class="muted"></div><div id="pagerTop" class="pager"></div><div id="list"></div><div id="pagerBottom" class="pager"></div></div><div class="box"><h3>تفاصيل السؤال</h3><div id="detail" class="muted">اختر سؤالًا</div></div></div>
</main><script>
let lessons=[],catalog={subjects:[],grades:[],curricula:[],terms:[],units:[]},pageOffset=0,pageSize=100,lastTotal=0;function h(){return {}}function saveKey(){location.href='/admin/login';msg.textContent='تم الحفظ';loadAll()}
async function jf(u,o={}){let r=await fetch(u,o),x=null;try{x=await r.json()}catch(e){}if(!r.ok)throw new Error((x&&x.detail)||('HTTP '+r.status));return x}
async function loadAll(){try{catalog=await jf('/api/academic/catalog');subject.innerHTML='<option value="">كل المواد</option>'+catalog.subjects.map(x=>`<option value="${x.id}">${x.name_ar}</option>`).join('');grade.innerHTML='<option value="">كل الصفوف</option>'+catalog.grades.map(x=>`<option value="${x.id}">${x.name_ar}</option>`).join('');curriculum.innerHTML='<option value="">كل إصدارات المنهج</option>'+catalog.curricula.map(x=>`<option value="${x.id}">${x.subject_name} — ${x.grade_name} — ${x.academic_year}</option>`).join('');lessons=await jf('/api/lessons');renderAcademicChildren();subject.onchange=()=>{renderAcademicChildren();resetPage()};grade.onchange=()=>{renderAcademicChildren();resetPage()};curriculum.onchange=()=>{renderAcademicChildren();resetPage()};term.onchange=()=>{renderAcademicChildren();resetPage()};unit.onchange=()=>{renderLessons();resetPage()};let chapters=[...new Set(lessons.map(x=>x.chapter))];chapter.innerHTML='<option value="">كل الأبواب</option>'+chapters.map(x=>`<option>${x}</option>`).join('');renderLessons();chapter.onchange=()=>{renderLessons();resetPage()};await loadStats();await loadQuestions()}catch(e){msg.textContent=e.message}}
function renderAcademicChildren(){let cv=curriculum.value?Number(curriculum.value):null;let terms=cv?catalog.terms.filter(x=>x.curriculum_version_id==cv):catalog.terms;term.innerHTML='<option value="">كل الترمات</option>'+terms.map(x=>`<option value="${x.id}">${x.name_ar}</option>`).join('');let tv=term.value?Number(term.value):null;let units=tv?catalog.units.filter(x=>x.term_id==tv):catalog.units;unit.innerHTML='<option value="">كل الوحدات</option>'+units.map(x=>`<option value="${x.id}">${x.title}</option>`).join('');renderLessons()}
function renderLessons(){let c=chapter.value;let arr=lessons.filter(x=>(!subject.value||x.subject_id==subject.value)&&(!grade.value||x.grade_level_id==grade.value)&&(!curriculum.value||x.curriculum_version_id==curriculum.value)&&(!term.value||x.term_id==term.value)&&(!unit.value||x.unit_id==unit.value)&&(!c||x.chapter==c));lesson.innerHTML='<option value="">كل الدروس</option>'+arr.map(x=>`<option value="${x.id}">${x.chapter} — ${x.title}</option>`).join('')}
async function loadStats(){let s=await jf('/api/admin/question-stats',{headers:h()});let t=s.totals||{};cards.innerHTML=[['إجمالي الأسئلة',t.total||0],['معتمد',t.approved||0],['غير معتمد',t.unapproved||0],['سهل',t.easy||0],['متوسط',t.medium||0],['صعب',t.hard||0],['غير مصنف',t.unclassified||0]].map(([a,b])=>`<div class=card><div class=muted>${a}</div><h2>${b}</h2></div>`).join('')}
function params(){let p=new URLSearchParams({limit:String(pageSize),offset:String(pageOffset)});if(subject.value)p.set('subject_id',subject.value);if(grade.value)p.set('grade_level_id',grade.value);if(curriculum.value)p.set('curriculum_version_id',curriculum.value);if(term.value)p.set('term_id',term.value);if(unit.value)p.set('unit_id',unit.value);if(chapter.value)p.set('chapter',chapter.value);if(lesson.value)p.set('lesson_id',lesson.value);if(qtype.value)p.set('question_type',qtype.value);if(difficulty.value)p.set('difficulty',difficulty.value);if(state.value)p.set('workflow_state',state.value);return p}
function resetPage(){pageOffset=0;loadQuestions()}
function renderPager(){let from=lastTotal?Math.min(pageOffset+1,lastTotal):0,to=Math.min(pageOffset+pageSize,lastTotal),html='<span class=muted>عرض '+from+'–'+to+' من '+lastTotal+'</span><span><button onclick="prevPage()" '+(pageOffset<=0?'disabled':'')+'>السابق</button> <button onclick="nextPage()" '+(pageOffset+pageSize>=lastTotal?'disabled':'')+'>التالي</button></span>';pagerTop.innerHTML=html;pagerBottom.innerHTML=html}
function prevPage(){pageOffset=Math.max(0,pageOffset-pageSize);loadQuestions()}
function nextPage(){if(pageOffset+pageSize<lastTotal){pageOffset+=pageSize;loadQuestions()}}
async function loadQuestions(){try{let x=await jf('/api/admin/question-catalog?'+params().toString(),{headers:h()}),qs=x.items||[];lastTotal=Number(x.total||0);count.textContent='عدد النتائج: '+lastTotal;list.innerHTML=qs.length?qs.map(q=>`<div class=q onclick='showQ(${JSON.stringify(q.id)})'><b>#${q.id}</b> · ${q.chapter||'بدون باب'} · ${q.lesson_title||'بدون درس'}<br><span class=tag>${q.question_type}</span><span class=tag>${q.difficulty}</span><span class=tag>${q.workflow_state}</span><br>${esc(String(q.text_verbatim).slice(0,180))}</div>`).join(''):'لا توجد نتائج';window._qs=qs;renderPager()}catch(e){msg.textContent=e.message;lastTotal=0;renderPager()}}
function showQ(id){let q=(window._qs||[]).find(x=>x.id==id);if(!q)return;detail.innerHTML=`<b>#${q.id}</b><p>${q.source_filename} — صفحة ${q.source_page||q.page}</p><p>${q.chapter||''} ${q.lesson_title||''}</p><p><span class=tag>${q.question_type}</span><span class=tag>${q.difficulty}</span><span class=tag>${q.workflow_state}</span></p><div class=detail>${esc(q.text_verbatim)}</div><p><a href="/admin/workflow">فتح في مسار المراجعة</a></p>`}
function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function resetFilters(){subject.value='';grade.value='';curriculum.value='';term.value='';unit.value='';chapter.value='';renderAcademicChildren();qtype.value='';difficulty.value='';state.value='';pageOffset=0;loadQuestions()}loadAll();
</script></html>'''

@app.get('/admin/bank',response_class=HTMLResponse)
def admin_bank():
    return BANK
